using CarCareTracker.External.Interfaces;
using CarCareTracker.Models;
using Npgsql;
using System.Text.Json;

namespace CarCareTracker.External.Implementations
{
    public class PGPartPurchaseDataAccess : IPartPurchaseDataAccess
    {
        private NpgsqlDataSource pgDataSource;
        private readonly ILogger<PGPartPurchaseDataAccess> _logger;
        private static string tableName = "partpurchases";
        public PGPartPurchaseDataAccess(IConfiguration config, ILogger<PGPartPurchaseDataAccess> logger)
        {
            pgDataSource = NpgsqlDataSource.Create(config["POSTGRES_CONNECTION"] ?? string.Empty);
            _logger = logger;
            try
            {
                //create table if not exist.
                string initCMD = $"CREATE SCHEMA IF NOT EXISTS app; CREATE TABLE IF NOT EXISTS app.{tableName} (id INT GENERATED BY DEFAULT AS IDENTITY primary key, vehicleId INT not null, partId INT not null, data jsonb not null)";
                using (var ctext = pgDataSource.CreateCommand(initCMD))
                {
                    ctext.ExecuteNonQuery();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
        }
        public List<PartPurchase> GetPartPurchasesByVehicleId(int vehicleId)
        {
            try
            {
                string cmd = $"SELECT data FROM app.{tableName} WHERE vehicleId = @vehicleId";
                var results = new List<PartPurchase>();
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    ctext.Parameters.AddWithValue("vehicleId", vehicleId);
                    using (NpgsqlDataReader reader = ctext.ExecuteReader())
                        while (reader.Read())
                        {
                            PartPurchase partPurchase = JsonSerializer.Deserialize<PartPurchase>(reader["data"] as string);
                            results.Add(partPurchase);
                        }
                }
                return results;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return new List<PartPurchase>();
            }
        }
        public List<PartPurchase> GetPartPurchasesByPartId(int partId)
        {
            try
            {
                string cmd = $"SELECT data FROM app.{tableName} WHERE partId = @partId";
                var results = new List<PartPurchase>();
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    ctext.Parameters.AddWithValue("partId", partId);
                    using (NpgsqlDataReader reader = ctext.ExecuteReader())
                        while (reader.Read())
                        {
                            PartPurchase partPurchase = JsonSerializer.Deserialize<PartPurchase>(reader["data"] as string);
                            results.Add(partPurchase);
                        }
                }
                return results;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return new List<PartPurchase>();
            }
        }
        public PartPurchase GetPartPurchaseById(int partPurchaseId)
        {
            try
            {
                string cmd = $"SELECT data FROM app.{tableName} WHERE id = @id";
                var result = new PartPurchase();
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    ctext.Parameters.AddWithValue("id", partPurchaseId);
                    using (NpgsqlDataReader reader = ctext.ExecuteReader())
                        while (reader.Read())
                        {
                            PartPurchase partPurchase = JsonSerializer.Deserialize<PartPurchase>(reader["data"] as string);
                            result = partPurchase;
                        }
                }
                return result;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return new PartPurchase();
            }
        }
        public bool DeletePartPurchaseById(int partPurchaseId)
        {
            try
            {
                string cmd = $"DELETE FROM app.{tableName} WHERE id = @id";
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    ctext.Parameters.AddWithValue("id", partPurchaseId);
                    return ctext.ExecuteNonQuery() > 0;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return false;
            }
        }
        public bool SavePartPurchaseToVehicle(PartPurchase partPurchase)
        {
            try
            {
                if (partPurchase.Id == default)
                {
                    string cmd = $"INSERT INTO app.{tableName} (vehicleId, partId, data) VALUES(@vehicleId, @partId, CAST(@data AS jsonb)) RETURNING id";
                    using (var ctext = pgDataSource.CreateCommand(cmd))
                    {
                        ctext.Parameters.AddWithValue("vehicleId", partPurchase.VehicleId);
                        ctext.Parameters.AddWithValue("partId", partPurchase.PartId);
                        ctext.Parameters.AddWithValue("data", "{}");
                        partPurchase.Id = Convert.ToInt32(ctext.ExecuteScalar());
                        //update json data
                        if (partPurchase.Id != default)
                        {
                            string cmdU = $"UPDATE app.{tableName} SET data = CAST(@data AS jsonb) WHERE id = @id";
                            using (var ctextU = pgDataSource.CreateCommand(cmdU))
                            {
                                var serializedData = JsonSerializer.Serialize(partPurchase);
                                ctextU.Parameters.AddWithValue("id", partPurchase.Id);
                                ctextU.Parameters.AddWithValue("data", serializedData);
                                return ctextU.ExecuteNonQuery() > 0;
                            }
                        }
                        return partPurchase.Id != default;
                    }
                }
                else
                {
                    string cmd = $"UPDATE app.{tableName} SET partId = @partId, data = CAST(@data AS jsonb) WHERE id = @id";
                    using (var ctext = pgDataSource.CreateCommand(cmd))
                    {
                        var serializedData = JsonSerializer.Serialize(partPurchase);
                        ctext.Parameters.AddWithValue("id", partPurchase.Id);
                        ctext.Parameters.AddWithValue("partId", partPurchase.PartId);
                        ctext.Parameters.AddWithValue("data", serializedData);
                        return ctext.ExecuteNonQuery() > 0;
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return false;
            }
        }
        public bool DeleteAllPartPurchasesByVehicleId(int vehicleId)
        {
            try
            {
                string cmd = $"DELETE FROM app.{tableName} WHERE vehicleId = @id";
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    ctext.Parameters.AddWithValue("id", vehicleId);
                    ctext.ExecuteNonQuery();
                    return true;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return false;
            }
        }
    }
}
